import numpy as np

def compute_probabilities(
    pheromone: np.ndarray,
    heuristic: np.ndarray,
    iteration: int,
    n_iterations: int
) -> np.ndarray:
    alpha = 1.0 + (iteration / n_iterations) * 0.5  # increase pheromone influence over time
    beta = 1.0 + (1 - iteration / n_iterations) * 0.5   # decrease heuristic influence over time
    return np.power(pheromone, alpha) * np.power(heuristic, beta)
